namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<string> _templates =
    [
        "Your build completed successfully.",
        "New comment on pull request #42.",
        "Deployment to production finished.",
        "Security scan found 0 vulnerabilities.",
        "Teammate requested your review.",
        "CI pipeline failed on branch 'feature/login'.",
        "Disk usage alert: 85% capacity reached.",
        "Scheduled maintenance window in 30 minutes.",
    ];

    /// <summary>Returns the initial batch of notifications.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        var initial = _templates.Take(3).Select(m => new Notification
        {
            Id = _nextId++,
            Message = m,
            Timestamp = DateTime.UtcNow
        }).ToList();

        return Task.FromResult(initial);
    }

    /// <summary>Simulates checking for new notifications (returns 0-1 randomly).</summary>
    public Task<List<Notification>> CheckForNewAsync()
    {
        var result = new List<Notification>();

        if (Random.Shared.Next(3) == 0) // ~33% chance each poll
        {
            var msg = _templates[Random.Shared.Next(_templates.Count)];
            result.Add(new Notification
            {
                Id = _nextId++,
                Message = msg,
                Timestamp = DateTime.UtcNow
            });
        }

        return Task.FromResult(result);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("T")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state or fetch once
        PersistedNotifications ??= await NotificationSvc.GetNotificationsAsync();
        notifications = PersistedNotifications;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only runs in the interactive render, never during prerender
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItems = await NotificationSvc.CheckForNewAsync();
                if (newItems.Count > 0)
                {
                    notifications.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

